scripts.linear_congruential:
def solve(inputs: dict) -> float:
    X = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    for _ in range(K):
        X = ((A * X) + B) % M

    return float(X)

scripts.modular_exponentiation:
def solve(inputs: dict) -> float:
    BASE = inputs['BASE']
    EXP = inputs['EXP']
    MOD = inputs['MOD']

    result = pow(BASE, EXP, MOD)
    return float(result)

